const fieldTypeColumnConfigMap: Record<string, Partial<GridColDef>> = {
  text: {
    width: 360,
    filterable: true,
  },
  textarea: {
    width: 360,
    filterable: true,
  },
  markdown: {
    width: 360,
    filterable: true,
  },
  wysiwyg_basic: {
    width: 360,
    valueFormatter: (value: any) => getHtmlText(value),
    filterable: true,
  },
  images: {
    width: 100,
    renderCell: (params: GridRenderCellParams) => {
      return <ImageCell params={params} />;
    },
  },
  link: {
    width: 360,
    filterable: true,
    renderCell: (params: any) => {
      return (
        <Link
          underline="hover"
          target="_blank"
          href={params.value}
          sx={{
            color: "primary.main",
            "&:hover": {
              textDecorationColor: (theme) => theme.palette.primary.main,
            },
          }}
          onClick={(e) => e.stopPropagation()}
        >
          {params.value}
        </Link>
      );
    },
  },
  currency: {
    width: 160,
    valueFormatter: (value: any) => {
      if (value === undefined || value === null) return "";

      return `${
        CURRENCY_OBJECT[value?.currency]?.symbol_native
      } ${new Intl.NumberFormat("en-US", {
        minimumFractionDigits: 2,
      }).format(value.value)}`;
    },
    align: "right",
  },
  number: {
    width: 160,
    valueFormatter: (value: any) => {
      if (!value) return null;
      return new Intl.NumberFormat("en-US").format(value);
    },
    filterable: true,
    align: "right",
  },
  yes_no: {
    width: 120,
    filterable: true,
  },
  color: {
    width: 140,
    filterable: true,
    renderCell: (params: GridRenderCellParams) => {
      return (
        <Box display="flex" alignItems="center" gap={1.5} height="100%">
          <Box
            sx={{
              width: 32,
              height: 32,
              borderRadius: "8px",
              backgroundColor: params.value,
              border: (theme) =>
                params.value?.toLowerCase() === "#ffffff"
                  ? `1px solid ${theme.palette.border}`
                  : "none",
            }}
          />
          <Typography variant="body2">{params.value?.toUpperCase()}</Typography>
        </Box>
      );
    },
  },
  dropdown: {
    width: 240,
    filterable: true,
  },
  sort: {
    width: 112,
    filterable: true,
  },
  uuid: {
    width: 280,
    filterable: true,
  },
};

type FieldTypeRepeaterProps = {
  field: ContentModelField;
};
export const FieldTypeRepeater = ({ field }: FieldTypeRepeaterProps) => {
  // TODO: For testing only. Dummy data
  const [dummyRows, setDummyRows] = useState(data);
  const apiRef = useGridApiRef();
  const [rowSelectionModel, setRowSelectionModel] =
    useState<GridRowSelectionModel>([]);
  const [rowDialog, setRowDialog] = useState<"add" | "edit" | null>(null);

  // TODO: Need to copy column config on ItemListTable
  const baseColumns: GridColDef[] = useMemo(() => {
    // FIXME: Just render text for other components using the stage changes provider
    return Object.keys(data[0]).map((key) => ({
      field: key,
      headerName: key,
      ...fieldTypeColumnConfigMap[key],
    }));
  }, [data]);

  const rows = useMemo(
    () =>
      dummyRows.map((item, index) => ({
        ...item,
        id: index,
      })),
    [dummyRows]
  );

  const columns: GridColDef[] = useMemo(() => {
    const hasSelectedRows = rowSelectionModel.length > 0;

    return baseColumns.map((col) => ({
      ...col,
      headerName: hasSelectedRows ? "" : col.headerName,
      renderHeader: hasSelectedRows
        ? (): React.ReactNode => null
        : col.renderHeader,
      disableColumnMenu: hasSelectedRows ? true : col.disableColumnMenu,
      sortable: hasSelectedRows ? false : col.sortable,
    }));
  }, [baseColumns, rowSelectionModel]);

  const calculatedHeight = useMemo(() => {
    const visibleRows = Math.min(rows.length, MAX_VISIBLE_ROWS);
    // Add 15px for horizontal scrollbar buffer if we have rows
    const hScrollBuffer = rows.length > 0 ? 15 : 0;
    return (
      HEADER_HEIGHT + visibleRows * ROW_HEIGHT + FOOTER_HEIGHT + hScrollBuffer
    );
  }, [rows.length]);

  return (
    <>
      <Box
        sx={{
          height: calculatedHeight,
          position: "relative",

          // An ancestor has removed all scrollbars so we're re-enabling them here
          "*": {
            scrollbarWidth: "auto",
            msOverflowStyle: "auto",
            "&::-webkit-scrollbar": {
              display: "auto",
            },
          },
        }}
      >
        {rowSelectionModel.length > 0 && (
          <IconButton
            onClick={() => {
              // Action for deletion can be added here
              setDummyRows((prev) =>
                prev.filter((_, index) => !rowSelectionModel.includes(index))
              );
              setRowSelectionModel([]);
            }}
            size="small"
            sx={{
              position: "absolute",
              top: 10,
              right: 12,
              zIndex: 100,
            }}
          >
            <DeleteIcon />
          </IconButton>
        )}
        <AutoSizer>
          {({ width, height }: Size) => (
            <DataGridPro
              rows={rows}
              apiRef={apiRef}
              columns={columns}
              checkboxSelection
              disableRowSelectionOnClick
              rowHeight={ROW_HEIGHT}
              columnHeaderHeight={HEADER_HEIGHT}
              pinnedColumns={{
                left: ["__check__"],
              }}
              rowSelectionModel={rowSelectionModel}
              onRowSelectionModelChange={(newModel) =>
                setRowSelectionModel(newModel)
              }
              onRowClick={(params) => {
                console.log(params);
              }}
              slots={{
                footer: () => (
                  <AddRowFooter
                    fieldName={field.label}
                    onAddRow={() => setRowDialog("add")}
                  />
                ),
              }}
              sx={{
                width,
                height,
                backgroundColor: "common.white",

                "& .MuiDataGrid-columnHeaderCheckbox": {
                  padding: 0,
                },

                "& .MuiDataGrid-scrollbarFiller": {
                  backgroundColor: "grey.100",
                },

                // Hide scrollbar for virtual scroller to avoid double scrollbars when a row is dynamically added
                "& .MuiDataGrid-virtualScroller": {
                  scrollbarWidth: "none",
                  msOverflowStyle: "none",
                  "&::-webkit-scrollbar": {
                    display: "none",
                  },
                },
              }}
            />
          )}
        </AutoSizer>
      </Box>
      {rowDialog && (
        <RowDialog onClose={() => setRowDialog(null)} name={field.label} />
      )}
    </>
  );
};
